import{_ as t,o as a,c as s,a5 as r}from"./chunks/framework.Bj-lFevX.js";const m=JSON.parse('{"title":"Augmenter Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/augmenters.md","filePath":"reference/augmenters.md"}'),i={name:"reference/augmenters.md"};function o(n,e,h,p,c,l){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="augmenter-reference" tabindex="-1">Augmenter Reference <a class="header-anchor" href="#augmenter-reference" aria-label="Permalink to &quot;Augmenter Reference&quot;">​</a></h1><p>This page is generated automatically from the <code>swagger-php</code> sources.</p><p>For improvements head over to <a href="https://github.com/zircote/swagger-php" target="_blank" rel="noreferrer">GitHub</a> and create a PR 😉</p><p>Augmenters enrich the collected specification with inferred data before compilation. They run in three groups — <strong>resolve</strong> (type inference, refs), <strong>reduce</strong> (filtering, cleanup), and <strong>augment</strong> (docblocks, operation ids, tags) — and are listed below in execution order.</p><p>Augmenters are part of the spec-attributes pipeline (<code>--mode spec</code> or <code>--mode hybrid</code>).</p><h2 id="augmenter-configuration" tabindex="-1">Augmenter Configuration <a class="header-anchor" href="#augmenter-configuration" aria-label="Permalink to &quot;Augmenter Configuration&quot;">​</a></h2><h3 id="command-line" tabindex="-1">Command line <a class="header-anchor" href="#command-line" aria-label="Permalink to &quot;Command line&quot;">​</a></h3><p>The <code>-c</code> option takes a name/value pair: the augmenter name (starting lowercase) and the option name, separated by a dot (<code>.</code>).</p><p>To list the available augmenter names and options use <code>-D</code>. It still requires a source path, e.g. <code>./vendor/bin/openapi --mode spec -D src</code>. Unknown keys are reported as warnings.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ./vendor/bin/openapi --mode spec -c operationIds.hash</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ./vendor/bin/openapi --mode spec -c pathFilter.tags[]=/pets/ -c pathFilter.tags[]=/store/ src</span></span></code></pre></div><h3 id="programmatically-with-php" tabindex="-1">Programmatically with PHP <a class="header-anchor" href="#programmatically-with-php" aria-label="Permalink to &quot;Programmatically with PHP&quot;">​</a></h3><p>Configuration can be set using the <code>Builder::withAugmenters()</code> method to access the pipeline and configure individual augmenters via <code>Pipeline::get()</code>.</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Builder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">withAugmenters</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ($pipeline) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        $pipeline</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Augmenter\\OperationIds</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setHash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        $pipeline</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Augmenter\\PathFilter</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setTags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">pets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">store</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    });</span></span></code></pre></div><h2 id="default-augmenters" tabindex="-1">Default Augmenters <a class="header-anchor" href="#default-augmenters" aria-label="Permalink to &quot;Default Augmenters&quot;">​</a></h2><h3 id="typealiases" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/TypeAliases.php" target="_blank" rel="noreferrer">TypeAliases</a> <a class="header-anchor" href="#typealiases" aria-label="Permalink to &quot;[TypeAliases](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/TypeAliases.php)&quot;">​</a></h3><p>Translates the type names classic accepts in an explicit <code>type</code> into OpenAPI types.</p><p>Classic maps <code>int</code>, <code>bool</code>, <code>long</code>, <code>float</code>, <code>double</code>, <code>date</code> and the date-time class names through {@see TypeMapper::NATIVE_TYPE_MAP}, so <code>type: &#39;long&#39;</code> becomes <code>integer</code> with format <code>int64</code>. The format is set only where none is given, and in a type list each name gets its type alone, as in classic. Each translation logs a deprecation. <code>mixed</code> and <code>byte</code> are left as they are, and the compiler reports them as unknown types.</p><p>Runs first, so every augmenter after it sees valid types, and a schema that <code>Inheritance</code> copies is translated, and reported, once.</p><p>@deprecated since 6.15, removed in 8.0 - write the OpenAPI type; {@see TypeAliasesRector} rewrites it</p><h4 id="config-settings" tabindex="-1">Config settings <a class="header-anchor" href="#config-settings" aria-label="Permalink to &quot;Config settings&quot;">​</a></h4><ul><li><strong>typeAliases.enabled</strong> : <code>bool</code> · default: <code>true</code><br> No details available.</li></ul><h3 id="inheritance" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Inheritance.php" target="_blank" rel="noreferrer">Inheritance</a> <a class="header-anchor" href="#inheritance" aria-label="Permalink to &quot;[Inheritance](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Inheritance.php)&quot;">​</a></h3><p>Handle all scenarios related to PHP inheritance.</p><p>Delegates to:</p><ul><li>Inheritance\\Schemas</li><li>Inheritance\\Operations</li></ul><h3 id="operationtags" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/OperationTags.php" target="_blank" rel="noreferrer">OperationTags</a> <a class="header-anchor" href="#operationtags" aria-label="Permalink to &quot;[OperationTags](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/OperationTags.php)&quot;">​</a></h3><p>Adds each tag declared on a method or a class to the operations declared there.</p><p>A tag on a method goes to that method&#39;s operations, and a tag on a class to every operation whose class it is, the ones on its methods included. An operation&#39;s own <code>tags</code> come first, then its method&#39;s, then its class&#39;s, each name once. A tag with no operations to go to, such as one on a class holding only <code>Info</code>, is left a declaration.</p><p>An operation belongs to the class its reflector names. For one inherited into a child controller that is the child, so it takes the child&#39;s class tags.</p><h3 id="impliedschemas" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/ImpliedSchemas.php" target="_blank" rel="noreferrer">ImpliedSchemas</a> <a class="header-anchor" href="#impliedschemas" aria-label="Permalink to &quot;[ImpliedSchemas](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/ImpliedSchemas.php)&quot;">​</a></h3><p>Adds the schemas the document&#39;s types imply but nobody declared.</p><p>A property, parameter or request body typed with a class that has no schema would lose its type, since only a component can be referenced. Where the class can be described without guessing, it is added as if it carried <code>#[OA\\Schema]</code>, and the augmenters after this one name, fill and reference it as they would a declared schema.</p><p>Today that is a PHP enum, whose cases are the whole description: <code>Names</code> names it, <code>Enums</code> fills its cases and <code>Types</code> references it. A backed enum&#39;s schema takes the backing type, so it lists the backing values, which is what a backed enum serialises to. A bare <code>#[OA\\Schema]</code> on the enum lists the case names instead.</p><h3 id="names" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Names.php" target="_blank" rel="noreferrer">Names</a> <a class="header-anchor" href="#names" aria-label="Permalink to &quot;[Names](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Names.php)&quot;">​</a></h3><p>Infers component keys from PHP reflectors when not explicitly set.</p><p>A component declared on a class is named after that class, so it can be referenced by class name. Declared anywhere else — a method, a parameter — the class reflector belongs to the <em>declaring</em> class, whose name is already taken by that class&#39;s own component, so nothing is inferred and the component stays inline.</p><p>A class carrying <code>#[OA\\Components]</code> is the exception: it is a holder, so each of its members declares a component of its own, named after the member.</p><p>A parameter is keyed differently: its <code>name</code> is its identity in OpenAPI, so a parameter component is keyed by it wherever it was declared, holder or not, and falls back to the class name only when it has no name either.</p><h3 id="enums" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Enums.php" target="_blank" rel="noreferrer">Enums</a> <a class="header-anchor" href="#enums" aria-label="Permalink to &quot;[Enums](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Enums.php)&quot;">​</a></h3><p>Expands PHP enums into schema enum values.</p><p>For schemas attached to a PHP enum, determines schema name, type, and enum values. Also resolves UnitEnum instances and enum class-strings in any schema&#39;s or server variable&#39;s enum array.</p><p>Rules for name vs. value:</p><ul><li>Unit enums (not backed): always use case names, type becomes &quot;string&quot;</li><li>Backed enums without explicit schema type: use case names, type becomes &quot;string&quot;</li><li>Backed enums with schema type matching backing type (int→&quot;integer&quot;, string→&quot;string&quot;): use backing values, type preserved</li><li>Backed enums with schema type NOT matching backing type: use case names</li></ul><h4 id="config-settings-1" tabindex="-1">Config settings <a class="header-anchor" href="#config-settings-1" aria-label="Permalink to &quot;Config settings&quot;">​</a></h4><ul><li><strong>enums.enumNames</strong> : <code>string</code> · default: <code>null</code><br> If set, stores enum case names in a vendor extension with this key (e.g. <code>x-enum-varnames</code>).</li></ul><h3 id="shortcuts" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Shortcuts.php" target="_blank" rel="noreferrer">Shortcuts</a> <a class="header-anchor" href="#shortcuts" aria-label="Permalink to &quot;[Shortcuts](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Shortcuts.php)&quot;">​</a></h3><p>Resolves shortcut attributes into the plain attributes they stand for.</p><p>A shortcut carries schema keywords on an attribute that holds a schema, so the common case needs no nested <code>OA\\Schema</code>. This augmenter moves those keywords to where the document has them.</p><p>Handles:</p><ul><li><code>OA\\MediaType\\Json</code> and <code>OA\\MediaType\\Xml</code>: their schema keywords move into the media type&#39;s <code>schema</code>;</li><li><code>OA\\Schema\\Items</code>: an array schema, whose item keywords move into a new <code>items</code> schema.</li></ul><h3 id="defaultmediatype" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/DefaultMediaType.php" target="_blank" rel="noreferrer">DefaultMediaType</a> <a class="header-anchor" href="#defaultmediatype" aria-label="Permalink to &quot;[DefaultMediaType](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/DefaultMediaType.php)&quot;">​</a></h3><p>Sets the media type of every <code>MediaType</code> that has none.</p><p>That is a bare <code>Schema</code> given as <code>content</code>, or a <code>MediaType</code> written without <code>mediaType</code>. A media type that is set is left alone, so an explicit one is how a single response or request body departs from the default.</p><h4 id="config-settings-2" tabindex="-1">Config settings <a class="header-anchor" href="#config-settings-2" aria-label="Permalink to &quot;Config settings&quot;">​</a></h4><ul><li><strong>defaultMediaType.mediaType</strong> : <code>string</code> · default: <code>application/json</code><br> The media type given to content that names none.</li></ul><h3 id="securityrequirements" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/SecurityRequirements.php" target="_blank" rel="noreferrer">SecurityRequirements</a> <a class="header-anchor" href="#securityrequirements" aria-label="Permalink to &quot;[SecurityRequirements](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/SecurityRequirements.php)&quot;">​</a></h3><p>Drops security requirements written as a bare scheme name.</p><p>Classic reads <code>security: [&#39;bearerAuth&#39;]</code> as <code>bearerAuth</code> with no scopes. Spec takes a <code>Security\\Requirement</code> per entry, so a string is reported and dropped. An operation left with no requirements falls back to the ones above it, rather than declaring itself public with an empty list.</p><p>Runs before <code>PathItems</code>, which clones path item requirements onto their operations.</p><h3 id="pathitems" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/PathItems.php" target="_blank" rel="noreferrer">PathItems</a> <a class="header-anchor" href="#pathitems" aria-label="Permalink to &quot;[PathItems](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/PathItems.php)&quot;">​</a></h3><p>Resolves PathItem prefixes, copies metadata to operations, and sets path-level output.</p><p>Composes path prefixes from the PathItems governing each operation&#39;s class, prepends them to operation paths, copies tags/security/responses to operations that don&#39;t declare their own, and marks PathItems that have spec-level output (parameters, summary, description, servers) with their resolved path. A PathItem governing several paths is written once per path.</p><p>Security requirements, responses and the per-path PathItems are deep copies, so a change made through one operation or path stays there.</p><p>The ancestor walk and the prefix composition belong to <code>Specification\\PathItemHierarchy</code>.</p><h3 id="types" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Types.php" target="_blank" rel="noreferrer">Types</a> <a class="header-anchor" href="#types" aria-label="Permalink to &quot;[Types](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Types.php)&quot;">​</a></h3><p>Infers schema type, format, nullable, items, etc. from PHP type declarations and docblocks.</p><p>Walks all properties and parameters in the specification and fills their schema fields from the attached reflector&#39;s type information.</p><h3 id="properties" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Properties.php" target="_blank" rel="noreferrer">Properties</a> <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;[Properties](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Properties.php)&quot;">​</a></h3><p>Infers an object schema&#39;s <code>required</code> list and its properties&#39; <code>default</code> from the PHP declarations.</p><p>A property is required when its PHP type is not nullable and it has no default, the rule a parameter follows, with the default counted too: a value exists when the field is left out. A promoted constructor property counts by its parameter&#39;s default. A property with no PHP type adds nothing to <code>required</code>.</p><p>A default is taken where it is a value the document can hold: a scalar, an enum case or an array of them. An enum case gives the value its schema lists: a backed case&#39;s value, a unit case&#39;s name. <code>null</code> is not taken, since the nullable type already says it, and neither is a value the schema&#39;s type does not admit.</p><p>What the attribute sets wins: an explicit <code>required</code> list is kept as written, and so is an explicit <code>default</code>, <code>null</code> included. Schemas converted from classic annotations are left alone.</p><p>Runs after <code>Augmenter\\Types</code>, which names each property and gives it the type its default is checked against.</p><h3 id="refs" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Refs.php" target="_blank" rel="noreferrer">Refs</a> <a class="header-anchor" href="#refs" aria-label="Permalink to &quot;[Refs](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Refs.php)&quot;">​</a></h3><p>Resolves FQCN-based $ref values to JSON Reference paths.</p><p>Builds a map of class names to their component paths and rewrites any $ref that looks like a FQCN into the proper #/components/... path. A ref that is neither a known class nor a pointer to an existing component is reported.</p><h3 id="parameters" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Parameters.php" target="_blank" rel="noreferrer">Parameters</a> <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;[Parameters](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Parameters.php)&quot;">​</a></h3><p>Gives a parameter that is only a <code>ref</code> the <code>name</code> and <code>in</code> of the component it points to.</p><p>OpenAPI tells two parameters apart by name and location. A <code>ref</code> parameter has neither of its own, so without them it cannot be matched with an inline parameter describing the same thing, and <code>Merge\\Operations</code> keeps both. Filled here, after <code>Augmenter\\Types</code> has named a parameter from its PHP parameter and <code>Augmenter\\Refs</code> has rewritten class name refs, every parameter reaching the merge carries its identity. It has to run before <code>Augmenter\\Merge</code>, which the phases see to: this is <code>Resolve</code>, and the merge is <code>Reduce</code> and later.</p><p>Only unset fields are filled, and the output does not change: a parameter with a <code>ref</code> is compiled to the reference alone.</p><h3 id="merge" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Merge.php" target="_blank" rel="noreferrer">Merge</a> <a class="header-anchor" href="#merge" aria-label="Permalink to &quot;[Merge](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Merge.php)&quot;">​</a></h3><p>Reduces every root collection to one entry per key, through the registered mergers.</p><p>Two attributes can claim one key, such as two operations on the same path and method, or two schemas named <code>Pet</code>. The merger that claims the type says what identifies it and what the survivor is, and one entry per key reaches the compiler.</p><p>Only the root collections, because that is where the two come from different places (a scan, a <code>withSpecification()</code> hook, the resolver, an inheritance clone), and something has to decide between them. A collision <em>inside</em> one attribute is two entries the same author wrote in one place. The compiler reports it and keeps its own last-write-wins.</p><p>Registered twice, and both are this class. The first run is the first pipe of the <strong>reduce</strong> phase, which is the earliest point every identity exists: <code>Augmenter\\PathItems</code> resolves an operation&#39;s path and <code>Augmenter\\Names</code> infers component keys, both in <strong>resolve</strong>. It is also before <code>Cleanup</code> and everything downstream that should see the survivor rather than both attributes. The second is the last pipe of all, so what a late augmenter adds is reduced too. It is a grouping over lists and costs nothing when there is nothing to do. An augmenter registered after it runs after it, and <code>insert()</code> is how to land ahead.</p><h3 id="pathfilter" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/PathFilter.php" target="_blank" rel="noreferrer">PathFilter</a> <a class="header-anchor" href="#pathfilter" aria-label="Permalink to &quot;[PathFilter](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/PathFilter.php)&quot;">​</a></h3><p>Filters operations by tag and/or path patterns.</p><p>If no tags or paths filters are set, no filtering is performed. All filter expressions must be valid regular expressions (with delimiters).</p><h4 id="config-settings-3" tabindex="-1">Config settings <a class="header-anchor" href="#config-settings-3" aria-label="Permalink to &quot;Config settings&quot;">​</a></h4><ul><li><strong>pathFilter.tags</strong> : <code>array</code> · default: <code>[]</code><br> A list of regular expressions to match <code>tags</code> to include.</li><li><strong>pathFilter.paths</strong> : <code>array</code> · default: <code>[]</code><br> A list of regular expressions to match <code>paths</code> to include.</li></ul><h3 id="cleanup" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Cleanup.php" target="_blank" rel="noreferrer">Cleanup</a> <a class="header-anchor" href="#cleanup" aria-label="Permalink to &quot;[Cleanup](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Cleanup.php)&quot;">​</a></h3><p>Removes unreferenced components from the specification.</p><p>Iterates multiple times to catch nested dependencies (a schema only referenced by another unused schema should also be removed).</p><p>Removal is reported once per run, as a notice with the count and the switch that turns it off; the components themselves are listed at debug level. A response component keyed by a status code is also reported on its own, as a warning, because it is a response that was meant to nest into an operation.</p><h4 id="config-settings-4" tabindex="-1">Config settings <a class="header-anchor" href="#config-settings-4" aria-label="Permalink to &quot;Config settings&quot;">​</a></h4><ul><li><strong>cleanup.enabled</strong> : <code>bool</code> · default: <code>true</code><br> Enables/disables removal of unreferenced components.</li></ul><h3 id="mediatypes" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/MediaTypes.php" target="_blank" rel="noreferrer">MediaTypes</a> <a class="header-anchor" href="#mediatypes" aria-label="Permalink to &quot;[MediaTypes](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/MediaTypes.php)&quot;">​</a></h3><p>Promotes property encodings and re-keys MediaType encoding lists by property name.</p><p>Promotes <code>OA\\Encoding</code> definitions from <code>OA\\Property\\Encoded</code> properties to their parent MediaType, then re-keys the encoding list as an associative array keyed by property name (the format the compiler expects).</p><h3 id="docblocks" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Docblocks.php" target="_blank" rel="noreferrer">Docblocks</a> <a class="header-anchor" href="#docblocks" aria-label="Permalink to &quot;[Docblocks](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Docblocks.php)&quot;">​</a></h3><p>Fills summary, description, and deprecated from PHP docblock comments.</p><p>Walks all attributes in the specification that have summary/description properties and populates them from the reflector&#39;s docblock when not explicitly set.</p><h3 id="operationidtemplates" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/OperationIdTemplates.php" target="_blank" rel="noreferrer">OperationIdTemplates</a> <a class="header-anchor" href="#operationidtemplates" aria-label="Permalink to &quot;[OperationIdTemplates](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/OperationIdTemplates.php)&quot;">​</a></h3><p>Expands the placeholders in an explicit operationId.</p><p><code>{method}</code> is replaced by the operation&#39;s method, as stored, in lowercase. Any other <code>{...}</code> is left as written.</p><h3 id="operationids" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/OperationIds.php" target="_blank" rel="noreferrer">OperationIds</a> <a class="header-anchor" href="#operationids" aria-label="Permalink to &quot;[OperationIds](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/OperationIds.php)&quot;">​</a></h3><p>Generates operationId for operations that don&#39;t have one explicitly set.</p><p>The id is derived from method, path and the declaring method, function or class. An operation with no reflector is identified by method and path alone.</p><h4 id="config-settings-5" tabindex="-1">Config settings <a class="header-anchor" href="#config-settings-5" aria-label="Permalink to &quot;Config settings&quot;">​</a></h4><ul><li><strong>operationIds.hash</strong> : <code>bool</code> · default: <code>true</code><br> If set to <code>true</code> generate ids (md5) instead of clear text operation ids.</li></ul><h3 id="tags" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Tags.php" target="_blank" rel="noreferrer">Tags</a> <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;[Tags](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/Tags.php)&quot;">​</a></h3><p>Ensures all tags used on operations exist in the global tags list.</p><p>Adds missing Tag objects for any tag name referenced by operations. Removes unused declared tags unless whitelisted.</p><h4 id="config-settings-6" tabindex="-1">Config settings <a class="header-anchor" href="#config-settings-6" aria-label="Permalink to &quot;Config settings&quot;">​</a></h4><ul><li><strong>tags.whitelist</strong> : <code>array</code> · default: <code>[]</code><br> Whitelist tags to keep even if not used. Use &#39;*&#39; to keep all.</li><li><strong>tags.withDescription</strong> : <code>bool</code> · default: <code>true</code><br> Enables/disables generation of default tag descriptions.</li></ul><h3 id="enumdescriptions" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Augmenter/EnumDescriptions.php" target="_blank" rel="noreferrer">EnumDescriptions</a> <a class="header-anchor" href="#enumdescriptions" aria-label="Permalink to &quot;[EnumDescriptions](https://github.com/zircote/swagger-php/tree/master/src/Augmenter/EnumDescriptions.php)&quot;">​</a></h3><p>Generates a description for enum-based properties.</p><h4 id="config-settings-7" tabindex="-1">Config settings <a class="header-anchor" href="#config-settings-7" aria-label="Permalink to &quot;Config settings&quot;">​</a></h4><ul><li><strong>enumDescriptions.enabled</strong> : <code>bool</code> · default: <code>false</code><br> Enables/disables generation of descriptions for enum based properties.</li></ul>`,119)])])}const g=t(i,[["render",o]]);export{m as __pageData,g as default};
